import urllib.request, json, time, email.utils
base='http://localhost:8080'
def req(path, token=None, method=None):
    headers={'Authorization':'Bearer '+token} if token else {}
    while True:
        request=urllib.request.Request(base+path, headers=headers, method=method)
        try:
            with urllib.request.urlopen(request, timeout=10) as response:
                return json.load(response)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code==429:
                wait=float(e.headers.get('Retry-After','1'))
                print(f'rate limited {path}: waiting {wait}s',flush=True); time.sleep(wait); continue
            if e.code==401:
                print(f'token expired at {path}; refreshing',flush=True)
                token=req('/token', method='POST')['token']
                headers['Authorization']='Bearer '+token
                continue
            raise RuntimeError(f'{path}: HTTP {e.code}: {body}')
token=req('/token',method='POST')['token']
all_items=[]
for page in range(1,31):
    try:
        data=req(f'/orders?page={page}', token)
    except RuntimeError as e:
        if '401' in str(e):
            token=req('/token',method='POST')['token']; data=req(f'/orders?page={page}',token)
        else: raise
    all_items.extend(data['items'])
    print('page',page,'items',len(data['items']),'next',data['next'],flush=True)
print('items total',len(all_items))
open('/tmp/orders.json','w').write(json.dumps(all_items))
